namespace ghidra.app.plugin.core.symboltree.nodes;






using docking.widgets.tree;
using generic.theme;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util.task;
using resources;

public class FunctionSymbolNode : SymbolNode {

	//@formatter:off
	static readonly DataFlavor LOCAL_DATA_FLAVOR = new SymbolTreeDataFlavor("Symbol Tree Data Flavor - Local Functions");
	static readonly DataFlavor GLOBAL_DATA_FLAVOR = new SymbolTreeDataFlavor("Symbol Tree Data Flavor - Global Functions");
	static readonly DataFlavor EXTERNAL_DATA_FLAVOR = new SymbolTreeDataFlavor("Symbol Tree Data Flavor - External Functions");

	public static readonly Icon FUNCTION_ICON = new GIcon("icon.plugin.symboltree.node.function");
	public static readonly Icon THUNK_ICON = new GIcon("icon.plugin.symboltree.node.function.thunk");
	public static readonly Icon EXTERNAL_ICON = new GIcon("icon.plugin.symboltree.node.function.external");
	public static readonly Icon DISABLED_FUNCTION_ICON = ResourceManager.getDisabledIcon(FUNCTION_ICON);
	public static readonly Icon DISABLED_THUNK_ICON = ResourceManager.getDisabledIcon(THUNK_ICON);
	public static readonly Icon DISABLED_EXTERNAL_ICON = ResourceManager.getDisabledIcon(EXTERNAL_ICON);
	//@formatter:on

	private static Comparator<GTreeNode> CHILD_COMPARATOR = new FunctionVariableComparator();

	private string tooltip;

	private bool isExternal;

	FunctionSymbolNode(Program program, Symbol symbol) : base(program, symbol)
    {
	}

	private bool isThunk() {
		Function func = (Function) symbol.getObject();
		if (func == null) {
			return false;
		}
		return func.isThunk();
	}

	/* @Override */
	public string getToolTip() {
		if (tooltip == null) {
			createTooltip();
		}
		return tooltip;
	}

	private void createTooltip() {
		Function func = (Function) symbol.getObject();
		if (func == null) {
			// unusual case
			tooltip = "No function for " + symbol.getName();
		}
		else {
			tooltip = ToolTipUtils.getToolTipText(func, true);
		}
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		bool cut = isCut();
		if (symbol.isExternal()) {
			return cut ? DISABLED_EXTERNAL_ICON : EXTERNAL_ICON;
		}
		else if (isThunk()) {
			return cut ? DISABLED_THUNK_ICON : THUNK_ICON;
		}
		return cut ? DISABLED_FUNCTION_ICON : FUNCTION_ICON;
	}

	/* @Override */
	public DataFlavor getNodeDataFlavor() {
		if (isExternal) {
			return EXTERNAL_DATA_FLAVOR;
		}
		return symbol.isGlobal() ? GLOBAL_DATA_FLAVOR : LOCAL_DATA_FLAVOR;
	}

	/* @Override */
	public bool canCut() {
		return true;
	}

	/* @Override */
	public Comparator<GTreeNode> getChildrenComparator() {
		return CHILD_COMPARATOR;
	}

	/* @Override */
	public GTreeNode findSymbolTreeNode(SymbolNode key, bool loadChildren,
			TaskMonitor taskMonitor) {

		Symbol searchSymbol = key.getSymbol();
		if (symbol == searchSymbol) {
			return this;
		}

		if (!isChildType(searchSymbol.getSymbolType())) {
			// the symbol is not a child type of a function (like another function or a library)
			return null;
		}

		return base.findSymbolTreeNode(key, loadChildren, taskMonitor);
	}

	private bool isChildType(SymbolType type) {
		//@formatter:off
		return type == SymbolType.PARAMETER || 
			   type == SymbolType.LOCAL_VAR ||
			   type == SymbolType.LABEL ||    // label function namespace 
			   type == SymbolType.NAMESPACE; // namespace in function namespace
		//@formatter:on
	}
//==================================================================================================
// Inner Classes
//==================================================================================================

	private static class FunctionVariableComparator : Comparator<GTreeNode> {
		/* @Override */
		public int compare(GTreeNode o1, GTreeNode o2) {
			SymbolNode symbolNode1 = (SymbolNode) o1;
			SymbolNode symbolNode2 = (SymbolNode) o2;

			Symbol symbol1 = symbolNode1.getSymbol();
			Symbol symbol2 = symbolNode2.getSymbol();

			object symbolObject1 = symbol1.getObject();
			object symbolObject2 = symbol2.getObject();

			if ((symbolObject1 is Variable) && (symbolObject2 is Variable)) {
				Variable v1 = (Variable) symbolObject1;
				Variable v2 = (Variable) symbolObject2;
				return v1.compareTo(v2);
			}
			if (symbolObject1 is Variable) {
				return -1;
			}
			if (symbolObject2 is Variable) {
				return 1;
			}

			return o1.compareTo(o2);
		}
	}
}
